import pathlib
import re

ROOT = pathlib.Path(__file__).resolve().parent.parent


def test_no_module_mentions_qty():
    offenders = [
        path.name
        for path in sorted((ROOT / "orders").glob("*.py"))
        if re.search(r"\bqty\b", path.read_text(encoding="utf-8"))
    ]
    assert offenders == []
